module top_module(
    input clk,
    input reset,
    input in,
    output done
);

    localparam IDLE = 2'b00, DATA = 2'b01, STOP = 2'b10, WAIT = 2'b11;
    reg [1:0] state, next_state;
    reg [3:0] cnt;

